using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using FVN_REGISTER.AI.Application.Abstractions;
using FVN_REGISTER.AI.Application.Contracts;
using FVN_REGISTER.AI.Infrastructure.Persistence;
using Microsoft.EntityFrameworkCore;

namespace FVN_REGISTER.AI.Infrastructure.Services;

public sealed class DocumentPipeline(
    AiPlatformDbContext db,IOriginalDocumentStore store,IMalwareScanner scanner,IDocumentTextExtractor textExtractor,IDocumentClassifier classifier,IDocumentRepresentationExtractor representationExtractor,IExtractionSchemaRegistry schemaRegistry,ISchemaDrivenDocumentExtractor structuredExtractor,IExtractionFieldMappingService mappingService,IExtractionValidationService validationService) : IDocumentPipeline
{
    private const string ParserVersion="local-text-v2"; private const int MaximumPipelineTextCharacters=2_000_000; private static readonly JsonSerializerOptions JsonOptions=new(JsonSerializerDefaults.Web);
    public async Task ProcessAsync(Guid documentId,string workerId,CancellationToken cancellationToken=default)
    {
        var now=DateTimeOffset.UtcNow;var leaseOwned=await db.IngestionJobs.AnyAsync(x=>x.DocumentId==documentId&&x.Status=="Running"&&x.LeaseOwner==workerId&&x.LeaseUntilUtc.HasValue&&x.LeaseUntilUtc.Value>now,cancellationToken);if(!leaseOwned)throw new InvalidOperationException("INGESTION_LEASE_LOST");
        var document=await db.Documents.SingleOrDefaultAsync(x=>x.Id==documentId,cancellationToken)??throw new InvalidOperationException("INGESTION_DOCUMENT_NOT_FOUND");if(document.Status is "Approved" or "Rejected" or "Archived")throw new InvalidOperationException("DOCUMENT_ALREADY_REVIEWED");
        await using var scanStream=await store.OpenReadAsync(document.StorageKey,cancellationToken);var scan=await scanner.ScanAsync(scanStream,cancellationToken);if(scan.Verdict!=MalwareScanVerdict.Clean){document.Status=scan.Verdict==MalwareScanVerdict.Infected?"Rejected":"Quarantined";if(document.Status=="Rejected")document.DedupActive=false;await db.SaveChangesAsync(cancellationToken);throw new InvalidOperationException(scan.FailureCode??(scan.Verdict==MalwareScanVerdict.Infected?"MALWARE_DETECTED":"MALWARE_SCAN_UNKNOWN"));}
        await using var content=await store.OpenReadAsync(document.StorageKey,cancellationToken);var rawText=await textExtractor.ExtractTextAsync(content,document.MediaType,cancellationToken);if(string.IsNullOrWhiteSpace(rawText))throw new InvalidDataException("EXTRACTION_EMPTY_DOCUMENT");var sourceTextTruncated=rawText.Length>MaximumPipelineTextCharacters;if(sourceTextTruncated)rawText=rawText[..MaximumPipelineTextCharacters];var representation=await representationExtractor.ExtractAsync(rawText,document.MediaType,cancellationToken);var modelText=representation.ToModelText();if(string.IsNullOrWhiteSpace(modelText))throw new InvalidDataException("EXTRACTION_EMPTY_REPRESENTATION");var(documentType,confidence)=await classifier.ClassifyAsync(modelText,cancellationToken);var classifierProvenance=classifier as IAIModelProvenance;var modelProvider=classifierProvenance?.ProviderName??"Unknown";var modelVersion=classifierProvenance?.ModelVersion??"Unknown";var fullTextHash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(modelText))).ToLowerInvariant();var representationJson=JsonSerializer.Serialize(representation,JsonOptions);
        object candidate;IReadOnlyList<ExtractionValidationIssue> validationIssues=[];var parserVersion=ParserVersion;var promptVersion="document-classification-v1";string? schemaCode=null;int? schemaVersion=null;var validationStatus="NotRun";string? validationSummaryJson=null;string provenanceJson;
        if(!string.IsNullOrWhiteSpace(document.ModuleCode)&&!string.IsNullOrWhiteSpace(document.SchemaCode))
        {
            var schema=await schemaRegistry.GetPublishedAsync(document.TenantCode,document.ModuleCode,document.SchemaCode,cancellationToken)??throw new InvalidOperationException("EXTRACTION_SCHEMA_NOT_PUBLISHED");
            var extracted=await structuredExtractor.ExtractAsync(modelText,schema,cancellationToken);var extractionProvenance=structuredExtractor as IAIModelProvenance;if(extractionProvenance is not null){modelProvider=extractionProvenance.ProviderName;modelVersion=extractionProvenance.ModelVersion;}
            var mapped=mappingService.Apply(schema,extracted);var validation=await validationService.ValidateAsync(new ExtractionValidationRequest(schema,mapped),cancellationToken);validationIssues=validation.Issues;validationStatus=validation.IsValid?"Valid":"Invalid";parserVersion="schema-extraction-v2";promptVersion="schema-extraction-v2";schemaCode=schema.SchemaCode;schemaVersion=schema.Version;validationSummaryJson=JsonSerializer.Serialize(new{status=validationStatus,schemaCode=schema.SchemaCode,schemaVersion=schema.Version,issueCount=validation.Issues.Count,errorCount=validation.Issues.Count(x=>string.Equals(x.Severity,"Error",StringComparison.OrdinalIgnoreCase)),acceptedCount=validation.AcceptedCandidates.Count,sourceTextTruncated,truncationLimit=sourceTextTruncated?MaximumPipelineTextCharacters:(int?)null},JsonOptions);provenanceJson=JsonSerializer.Serialize(new{source=new{documentId=document.Id,sha256=document.Sha256,sourceType=document.SourceType,sourceReference=document.SourceReference},representation=new{version=representation.Version,mediaType=representation.MediaType,isOcr=representation.IsOcr,textSha256=fullTextHash},schema=new{schemaCode=schema.SchemaCode,schemaVersion=schema.Version},model=new{provider=modelProvider,version=modelVersion,promptVersion},processing=new{sourceTextTruncated,truncationLimit=sourceTextTruncated?MaximumPipelineTextCharacters:(int?)null},mapping=schema.Mappings?.Select(x=>new{x.TargetPath,x.SourceHints,x.Normalization}).ToArray()},JsonOptions);var standardized=new StandardizedExtractionResult(schema.SchemaCode,schema.Version,mapped,validation,representation.Version,fullTextHash,parserVersion,modelProvider,modelVersion,promptVersion);candidate=new{standardized,documentId=document.Id,fileName=document.FileName,documentType,source=new{sha256=document.Sha256},warnings=sourceTextTruncated?new[]{"AI extraction is a candidate and requires human review.","Source text exceeded the 2,000,000 character pipeline limit and was truncated.","No official business data has been changed."}:new[]{"AI extraction is a candidate and requires human review.","No official business data has been changed."}};
        }
        else
        {
            candidate=BuildCandidate(document,documentType,modelText,sourceTextTruncated);provenanceJson=JsonSerializer.Serialize(new{source=new{documentId=document.Id,sha256=document.Sha256,sourceType=document.SourceType,sourceReference=document.SourceReference},representation=new{version=representation.Version,mediaType=representation.MediaType,isOcr=representation.IsOcr,textSha256=fullTextHash},model=new{provider=modelProvider,version=modelVersion,promptVersion},processing=new{sourceTextTruncated,truncationLimit=sourceTextTruncated?MaximumPipelineTextCharacters:(int?)null}},JsonOptions);
        }
        var release=await db.Set<AiModelReleaseRecord>().AsNoTracking().Where(x=>x.TenantCode==document.TenantCode&&(x.Status=="Candidate"||x.Status=="Active")&&x.ModelProvider==modelProvider&&x.ModelVersion==modelVersion&&x.PromptVersion==promptVersion&&x.SchemaCode==schemaCode&&x.SchemaVersion==schemaVersion).OrderByDescending(x=>x.Status=="Candidate").ThenByDescending(x=>x.CreatedAtUtc).FirstOrDefaultAsync(cancellationToken);
        var extraction=new AiExtractionRecord{Id=Guid.NewGuid(),DocumentId=document.Id,TenantCode=document.TenantCode,ReleaseId=release?.Id,DocumentType=documentType,ClassificationConfidence=(decimal)confidence,SchemaCode=schemaCode,SchemaVersion=schemaVersion,ValidationStatus=validationStatus,CandidateJson=JsonSerializer.Serialize(candidate,JsonOptions),RepresentationJson=representationJson,ValidationSummaryJson=validationSummaryJson,ProvenanceJson=provenanceJson,ParserVersion=parserVersion,ModelProvider=modelProvider,ModelVersion=modelVersion,PromptVersion=promptVersion,CreatedAtUtc=DateTimeOffset.UtcNow};db.Extractions.Add(extraction);foreach(var issue in validationIssues)db.ValidationIssues.Add(new AiValidationIssueRecord{Id=Guid.NewGuid(),TenantCode=document.TenantCode,ExtractionId=extraction.Id,FieldPath=issue.Path,RuleCode=issue.Code,Severity=issue.Severity,Message=issue.Message,CreatedAtUtc=DateTimeOffset.UtcNow});document.Status="AwaitingHumanReview";await db.SaveChangesAsync(cancellationToken);
    }
    private static object BuildCandidate(AiDocumentRecord document,string type,string text,bool sourceTextTruncated){var lines=text.Replace("\r\n","\n").Replace('\r','\n').Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries);var evidenceRows=new List<object>();var pageNumber=1;for(var index=0;index<Math.Min(lines.Length,500);index++){var line=lines[index];var pageMarker=System.Text.RegularExpressions.Regex.Match(line,@"^\[PAGE (?<page>\d+)\]$");if(pageMarker.Success&&int.TryParse(pageMarker.Groups["page"].Value,out var parsedPage)){pageNumber=parsedPage;continue;}if(DocumentCandidateText.IsNoiseLine(line))continue;evidenceRows.Add(new{lineNumber=index+1,pageNumber,locator=$"page:{pageNumber};line:{index+1}",text=line.Length>4000?line[..4000]:line});}var fields=new Dictionary<string,object?>{["dateCandidates"]=DocumentCandidateText.ExtractDateCandidates(text),["timeCandidates"]=System.Text.RegularExpressions.Regex.Matches(text,@"\b(?:[01]?\d|2[0-3]):[0-5]\d\b").Select(m=>m.Value).Distinct().Take(100).ToArray(),["numericCandidates"]=System.Text.RegularExpressions.Regex.Matches(text,@"(?<!\w)-?\d+(?:[.,]\d+)?").Select(m=>m.Value).Distinct().Take(200).ToArray(),["hourCandidates"]=System.Text.RegularExpressions.Regex.Matches(text,@"(?i)\b(?<value>\d{1,3}(?:[.,]\d{1,2})?)\s*(?:giờ|hours?|h)\b").Select(m=>m.Groups["value"].Value).Distinct().Take(100).ToArray(),["dayCandidates"]=System.Text.RegularExpressions.Regex.Matches(text,@"(?i)\b(?<value>\d{1,3}(?:[.,]\d{1,2})?)\s*(?:ngày|days?)\b").Select(m=>m.Groups["value"].Value).Distinct().Take(100).ToArray(),["emailCandidates"]=System.Text.RegularExpressions.Regex.Matches(text,@"(?i)\b[^\s@]+@[^\s@]+\.[^\s@]+\b").Select(m=>m.Value).Distinct().Take(100).ToArray()};var warnings=sourceTextTruncated?new[]{"Candidate is machine-generated and requires human verification.","Source text exceeded the 2,000,000 character pipeline limit and was truncated.","No official HR record has been changed."}:new[]{"Candidate is machine-generated and requires human verification.","No official HR record has been changed."};return new{schemaVersion="1.0",documentId=document.Id,fileName=document.FileName,documentType=type,source=new{sha256=document.Sha256},extractedFields=fields,evidence=evidenceRows.ToArray(),fullTextSha256=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(text))).ToLowerInvariant(),warnings};}
}
